/**
 * 1. insert monitor_conf_event table
 * 2. config 增加 prometheus rule cmdline flt模板
 * 3. sys_menu 表增加 icon 字段
 */

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for monitor_conf_event
-- ----------------------------
DROP TABLE IF EXISTS `monitor_conf_event`;
CREATE TABLE `monitor_conf_event`  (
  `table` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `value` bigint(20) NULL DEFAULT 0,
  PRIMARY KEY (`table`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of monitor_conf_event
-- ----------------------------
INSERT INTO `monitor_conf_event` VALUES ('blackbox', 0);
INSERT INTO `monitor_conf_event` VALUES ('cmd', 0);
INSERT INTO `monitor_conf_event` VALUES ('global', 0);
INSERT INTO `monitor_conf_event` VALUES ('per-datacenter', 0);
INSERT INTO `monitor_conf_event` VALUES ('snmp', 0);


DELETE from sys_config where param_key = "prom_cmd_tmpl";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'prom_cmd_tmpl', 'OPTION=\" --config.file=\'/opt/nezha/nz-confagent/prometheus/prometheus.yml\' --web.listen-address=\'127.0.0.1:9090\' --web.enable-admin-api --storage.tsdb.path=\'/data/prometheusData\'  --web.enable-lifecycle --storage.tsdb.retention.time=${storageDays}d \"', 1, 'prometheus 启动参数模板');

DELETE from sys_config where param_key = "prom_yml_tmpl";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'prom_yml_tmpl', '{\r\n    \"global\": {\r\n        \"scrape_interval\": \"${scrape_interval}s\",\r\n        \"scrape_timeout\": 	<#if scrape_timeout??> \r\n								\"${scrape_timeout}s\",\r\n						    <#else>\r\n								\"10s\",\r\n							</#if>\r\n        \"evaluation_interval\": \"${scrape_interval}s\"\r\n    },\r\n	\r\n	<#-- alert 配置 -->\r\n	<#if isAlert>\r\n	\"alerting\": {\r\n		\"alertmanagers\": [{\r\n			\"path_prefix\": \"${path_prefix}\",\r\n			\"static_configs\": [{\r\n				\"targets\": [\"${alert_url}\"]\r\n			}]\r\n		}],\r\n		\"alert_relabel_configs\": [{\r\n			\"regex\": \"instance\",\r\n			\"action\": \"labeldrop\"\r\n		}, {\r\n			\"regex\": \"replica\",\r\n			\"action\": \"labeldrop\"\r\n		}]\r\n	},\r\n	\"rule_files\": [\"rule.yml\"],\r\n	</#if>\r\n	\r\n	\r\n	\r\n	<#-- per-datacenter 配置 -->\r\n	<#if !isGlobal>\r\n    \"scrape_configs\": [\r\n		<#list endpointList as endpoint>\r\n			{\r\n				\"job_name\": ${endpoint.id?c},\r\n				\"metrics_path\": <#if endpoint.config.metrics_path?default(\"\")?trim?length gt 1>\r\n									\"${endpoint.config.metrics_path}\",\r\n								<#else>\r\n									\"/metric\",\r\n								</#if>\r\n				\"scrape_interval\": 	<#if endpoint.config.scrape_interval?default(\"\")?trim?length gt 1>\r\n										\"${endpoint.config.scrape_interval}s\",\r\n									<#else>\r\n										\"${scrape_interval}s\",\r\n									</#if>\r\n				\"scrape_timeout\": 	<#if endpoint.config.scrape_timeout?default(\"\")?trim?length gt 1>\r\n										\"${endpoint.config.scrape_timeout}s\",\r\n									<#else>\r\n										<#if scrape_timeout??> \r\n											\"${scrape_timeout}s\",\r\n										<#else>\r\n											\"10s\",\r\n										</#if>\r\n									</#if>\r\n\r\n				\r\n				<#if endpoint.config.basic_auth??&& (endpoint.config.basic_auth?size >0)>\r\n                \"basic_auth\":{\r\n                    \"username\": <#if endpoint.config.basic_auth.username?default(\"\")?trim?length gt 1>\r\n                                \"${endpoint.config.basic_auth.username}\",\r\n                                <#else>\"\",</#if>\r\n                    \"password\": <#if endpoint.config.basic_auth.password?default(\"\")?trim?length gt 1>\r\n                                \"${endpoint.config.basic_auth.password}\"\r\n                                <#else>\"\"</#if>\r\n                    },\r\n				</#if>\r\n				\r\n				\r\n				<#if endpoint.config.bearer_token??> \r\n				\"authorization\":{\r\n						\"type\":\"Bearer\",\r\n						\"credentials\":\"${endpoint.config.bearer_token}\"\r\n					},\r\n				</#if>\r\n\r\n				\r\n				<#-- params 不为空且类型为 http ，添加 params -->\r\n				<#if endpoint.config.params??&& (endpoint.config.params?size >0) && endpoint.module.type == \"http\">\r\n				\"params\":{\r\n					<#list endpoint.config.params?keys as itemKey>\r\n					\"${itemKey}\":[\r\n						<#list endpoint.config.params[itemKey] as pojo>\r\n							\"${pojo}\"\r\n							<#sep>,</#sep>\r\n						</#list>\r\n						]\r\n						<#sep>,</#sep>\r\n					</#list>\r\n				},\r\n				<#elseif endpoint.module.type == \"snmp\">\r\n				<#-- 类型是 snmp ，组织 param 数据 ， 原来params弃用，因为 snmp_exporter 不支持其他参数 -->\r\n			   \"params\":{\r\n					\"target\":[ \"${endpoint.host}:${endpoint.port?c}\" ],\r\n					\"module\":[ \"${endpoint.module.name}\" ]\r\n				},\r\n				</#if>\r\n				\r\n				\"static_configs\": [{\r\n					\"targets\": [<#if endpoint.module.type == \"http\">\r\n									\"${endpoint.host}:${endpoint.port?c}\"\r\n								<#else>\r\n									\"127.0.0.1:9116\"\r\n								</#if>\r\n								],\r\n					\"labels\": {\r\n						\"datacenter\": 	<#if endpoint.config.labels??&&endpoint.config.labels.datacenter?default(\"\")?trim?length gt 1>\r\n											\"${endpoint.config.labels.datacenter}\",\r\n										<#else>\r\n											\"${endpoint.dc.name}\",\r\n										</#if>\r\n						\"project\": 		<#if endpoint.config.labels??&&endpoint.config.labels.project?default(\"\")?trim?length gt 1>\r\n											\"${endpoint.config.labels.project}\",\r\n										<#else>\r\n											\"${endpoint.project.name}\", \r\n										</#if>\r\n						\"asset\": 		<#if endpoint.config.labels??&&endpoint.config.labels.asset?default(\"\")?trim?length gt 1>\r\n											\"${endpoint.config.labels.asset}\",\r\n										<#else>\r\n											\"${endpoint.asset.manageIp}\",\r\n										</#if>\r\n						\"module\": 		<#if endpoint.config.labels??&&endpoint.config.labels.module?default(\"\")?trim?length gt 1>\r\n											\"${endpoint.config.labels.module}\"\r\n												<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n													,\r\n												</#if>\r\n										<#else>\r\n											\"${endpoint.module.name}\"\r\n												<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n													,\r\n												</#if>\r\n										</#if>\r\n										\r\n										<#-- 补充用户自定义 Labels -->\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											<#list endpoint.config.labels?keys as key>\r\n												<#if key != \"datacenter\" &&  key != \"module\" &&  key != \"project\" &&  key != \"asset\">\r\n													\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n												</#if>\r\n											 </#list>\r\n										</#if>\r\n					}\r\n				}],\r\n				\"relabel_configs\": [\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					{\r\n						\"source_labels\": [\r\n							\"job\"\r\n						],\r\n						\"regex\": \"(.+)\",\r\n						\"target_label\": \"endpoint\"\r\n					},\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				]\r\n			}\r\n			<#sep>,</#sep>\r\n		</#list>\r\n    ]\r\n	<#else>\r\n	<#-- global 配置 -->\r\n	\"scrape_configs\": [\r\n		<#list jobList as jobPojo>\r\n			{\r\n			   \"job_name\": \"${jobPojo.job_name}\",\r\n				<#if jobPojo.isFederate> \r\n				\"honor_labels\": ${jobPojo.honor_labels},\r\n				\"params\": {\r\n					\"match[]\": [\r\n						\"{__name__=~\\\".+\\\"}\"\r\n					]\r\n				},\r\n				\"authorization\":{\r\n					\"type\":\"Bearer\",\r\n					\"credentials\":\"${jobPojo.token}\"\r\n				},\r\n				</#if>\r\n				\"metrics_path\": <#if jobPojo.metrics_path?default(\"\")?trim?length gt 1>\r\n									\"${jobPojo.metrics_path}\",\r\n								<#else>\r\n									\"/metric\",\r\n								</#if>\r\n				\"static_configs\":[\r\n					<#list jobPojo.staticConfigList as staticConf >\r\n						{\r\n						  \"targets\": [\r\n								<#list staticConf.targets as targetConf>\r\n										\"${targetConf}\"<#sep>,</#sep>\r\n								</#list>\r\n							]\r\n						<#if staticConf.labels ??&& (staticConf.labels?size >0)>\r\n						   ,\r\n						   \"labels\": {\r\n								<#list staticConf.labels?keys as itemKey>\r\n									\"${itemKey}\":<#if staticConf.labels[itemKey]?default(\"\")?trim?length gt 1>\r\n													\"${staticConf.labels[itemKey]}\"\r\n												  <#else>\"\"</#if><#sep>,</#sep>\r\n								</#list>\r\n							} \r\n						</#if>\r\n						}<#sep>,</#sep>\r\n					</#list>\r\n					],\r\n				\"relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					<#if jobPojo.instanceRelabel> \r\n					,\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					</#if>\r\n				],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				]\r\n			}<#sep>,</#sep>\r\n		</#list>\r\n	]\r\n	</#if>\r\n}', 1, 'prometheus config文件模板');

DELETE from sys_config where param_key = "prom_rule_tmpl";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'prom_rule_tmpl', '{\r\n	\"groups\": [{\r\n		\"name\": \"alertRule\",\r\n		\"rules\": [\r\n            <#if endpointAlert>\r\n            {\r\n				\"alert\": \"0\",\r\n				\"expr\": \"up{endpoint!=\'\'}>-1\",\r\n				\"for\": \"30s\",\r\n				\"annotations\": {\r\n					\"summary\": \"{{$value}}\"\r\n				}\r\n			}, \r\n             </#if>\r\n             <#list ruleList as rule>\r\n            {\r\n				\"alert\":  ${rule.id?c},\r\n				\"expr\": \"(${rule.expr})${rule.operator}${rule.threshold}\",\r\n				\"for\": \"${rule.last}s\",\r\n				\"labels\": {\r\n					\"severity\": \"${rule.severity_name}\",\r\n					\"severity_id\": ${rule.severity_id?c}\r\n				},\r\n				\"annotations\": {\r\n					\"summary\": <#if rule.summary?default(\"\")?trim?length gt 1>\r\n                                \"${rule.summary}\",\r\n                      <#else>\"\",</#if>\r\n					\"description\": <#if rule.description?default(\"\")?trim?length gt 1>\r\n                                \"${rule.description}\"\r\n                      <#else>\"\"</#if>\r\n					\r\n				}\r\n			}\r\n			<#sep>,</#sep>\r\n		</#list>]\r\n	}]\r\n}', 1, 'prometheus rule文件模板');

ALTER TABLE sys_menu ADD COLUMN `icon` varchar(128) DEFAULT '' COMMENT 'nz-icon nz-alert-add';

SET FOREIGN_KEY_CHECKS = 1;
